### 3. Set Up App Integration

Update `app/components/_app/index.jsx` to initialize Page Designer:

```jsx
import {PageDesignerProvider} from '@salesforce/commerce-sdk-react/components'
import {useUsid} from '@salesforce/commerce-sdk-react'
import {initializeRegistry} from '@salesforce/retail-react-app/app/page-designer/registry'
import {PageDesignerInit} from '@salesforce/retail-react-app/app/components/page-designer-init'

// Initialize registry synchronously at module load time so components are available during SSR
initializeRegistry()

const App = (props) => {
  const {children} = props
  const {usid} = useUsid()

  // Detect Page Designer mode from URL
  const pageDesignerMode = useMemo(() => {
    const queryParams = location?.search || ''
    if (queryParams.includes('mode=EDIT')) return 'EDIT'
    if (queryParams.includes('mode=PREVIEW')) return 'PREVIEW'
    return undefined
  }, [])

  return (
    <Box className="sf-app">
      <PageDesignerProvider
        clientId="pwa-kit-client"
        targetOrigin="*"
        usid={usid}
        mode={pageDesignerMode}
      >
        <PageDesignerInit />
        {children}
      </PageDesignerProvider>
    </Box>
  )
}
```

### Design Mode Detection

Use the `usePageDesignerMode` hook to conditionally render content based on design mode:

```jsx
import {usePageDesignerMode} from '@salesforce/commerce-sdk-react/components'

function MyComponent() {
  const {isDesignMode, isPreviewMode} = usePageDesignerMode()

  return (
    <div>
      {isDesignMode && <span>Editing mode</span>}
      {/* ... */}
    </div>
  )
}
```

Or use the utility functions for checking outside of React components:

```jsx
import {isDesignModeActive, isPreviewModeActive} from '@salesforce/commerce-sdk-react/components'

if (isDesignModeActive()) {
  // In design mode
}
```

# Caching

Custom APIs support the caching of responses. For more information on caching strategies, see [Caching Strategies for Salesforce B2C Commerce].

To use caching for your Custom API endpoints, enable *Page Caching* for the sites using the Custom API. After that, a response can be cached in the implementation script in these ways:

- Use the `dw.system.Response#setExpires(milliseconds)` Script API method [as described here] to set the cache time.
- Use the `dw.system.Response#setVaryBy(identifier)` Script API method [as described here] to mark the response as personalized. Use this with caution as it might result in performance degradation in places where the response is not actually personalized.

**Example 1:** An implementation of a custom product API that caches responses for 60 seconds:

```javascript
var RESTResponseMgr = require("dw/system/RESTResponseMgr");

exports.getCustomProduct = function () {
  var customProduct = // ... some lookup of custom product data ...

  // set cache time to 60 seconds
  response.setExpires(Date.now() + 60000);

  RESTResponseMgr.createSuccess(customProduct).render();
};

exports.getCustomProduct.public = true;
```

**Example 2:** An implementation of a custom product API that caches responses based on promotion:

```javascript
var RESTResponseMgr = require("dw/system/RESTResponseMgr");

exports.getCustomProduct = function () {
  var customProduct = // ... some lookup of custom product data ...

  // set caching based on promotion    
  response.setVaryBy("price_promotion");

  RESTResponseMgr.createSuccess(customProduct).render();
};

exports.getCustomProduct.public = true;
```

