### Migration Steps

#### Step 1: Install Required Dependency

Add the `@salesforce/storefront-next-runtime` package to your project:

```bash
npm install @salesforce/storefront-next-runtime
```

Update your `package.json`:

```json
{
  "dependencies": {
    "@salesforce/storefront-next-runtime": "^VERSION",
    "@salesforce/commerce-sdk-react": "^VERSION"
  }
}
```

#### Step 2: Update Component Metadata to Headless

For **each existing component** in your cartridge, update the JSON metadata file to include `arch_type: "headless"`:

**Before** (`cartridge/experience/components/commerce_assets/photoTile.json`):

```json
{
    "name": "Photo Tile",
    "description": "Image display component",
    "group": "commerce_assets",
    "attribute_definition_groups": [...]
}
```

**After**:

```json
{
    "name": "Photo Tile",
    "description": "Image display component",
    "group": "commerce_assets",
    "arch_type": "headless",
    "region_definitions": [],
    "attribute_definition_groups": [...]
}
```

**Required changes for each component**:

- Add `"arch_type": "headless"`.
- Add `"region_definitions": []` for leaf components, or populate with regions for layout components.

#### Step 3: Update Page Metadata with Routes

For **each existing page** in your cartridge, update the JSON metadata to include `arch_type` and `route`:

**Before** (`cartridge/experience/pages/homePage.json`):

```json
{
    "name": "Home Page",
    "description": "Main landing page",
    "region_definitions": [...]
}
```

**After**:

```json
{
    "name": "Home Page",
    "description": "Main landing page",
    "arch_type": "headless",
    "route": "/",
    "region_definitions": [...]
}
```

**Route examples**:

- Homepage: `"route": "/"`
- Static pages: `"route": "/about"`, `"route": "/contact"`
- Product pages: `"route": "/product/:productId"` (`:productId` matches the attribute ID in your aspect type)
- Category pages: `"route": "/category/:categoryId"` (`:categoryId` matches the attribute ID in your aspect type)

#### Step 4: Update Aspect Type Metadata

For **each aspect type** (PDP, PLP, Search), add `arch_type`:

**Before** (`cartridge/experience/aspects/pdp.json`):

```json
{
    "name": "Product detail page",
    "description": "A product detail page",
    "attribute_definitions": [...],
    "supported_object_types": ["product"]
}
```

**After**:

```json
{
    "name": "Product detail page",
    "description": "A product detail page",
    "arch_type": "headless",
    "attribute_definitions": [...],
    "supported_object_types": ["product"]
}
```

#### Step 5: Migrate from Manual Mapping to Registry

Replace the old manual component mapping with the new registry approach.

**Remove** the old mapping pattern from your page-viewer:

```jsx
// OLD - Remove this
const PAGEDESIGNER_TO_COMPONENT = {
    'commerce_assets.photoTile': ImageTile,
    'commerce_layouts.carousel': Carousel,
    // ...
}

<Page page={page} components={PAGEDESIGNER_TO_COMPONENT} />
```

**Create** a registry file at `app/page-designer/registry.js`:

```jsx
import {registry} from '@salesforce/commerce-sdk-react'

export function initializeRegistry() {
  // Commerce Assets
  registry.registerImporter('commerce_assets.imageTile', () => import('./assets/image-tile'))
  registry.registerImporter('commerce_assets.imageAndText', () =>
    import('./assets/image-with-text')
  )
  registry.registerImporter('commerce_assets.productTile', () => import('./assets/product-tile'))

  // Commerce Layouts
  registry.registerImporter('commerce_layouts.carousel', () => import('./layouts/carousel'))
  registry.registerImporter('commerce_layouts.mobileGrid1r1c', () =>
    import('./layouts/mobileGrid1r1c')
  )
  registry.registerImporter('commerce_layouts.mobileGrid2r1c', () =>
    import('./layouts/mobileGrid2r1c')
  )
  registry.registerImporter('commerce_layouts.mobileGrid2r2c', () =>
    import('./layouts/mobileGrid2r2c')
  )
  registry.registerImporter('commerce_layouts.mobileGrid2r3c', () =>
    import('./layouts/mobileGrid2r3c')
  )
  registry.registerImporter('commerce_layouts.mobileGrid3r1c', () =>
    import('./layouts/mobileGrid3r1c')
  )
  registry.registerImporter('commerce_layouts.mobileGrid3r2c', () =>
    import('./layouts/mobileGrid3r2c')
  )
}
```

**Update** your page-viewer to use the registry:

```jsx
// app/pages/page-viewer/index.jsx
import React from 'react'
import {useParams} from 'react-router-dom'
import {Box} from '@salesforce/retail-react-app/app/components/shared/ui'
import {usePage} from '@salesforce/commerce-sdk-react'
import {Page} from '@salesforce/commerce-sdk-react/components'
import {HTTPError, HTTPNotFound} from '@salesforce/pwa-kit-react-sdk/ssr/universal/errors'

const PageViewer = () => {
  const {pageId} = useParams()
  const {data: page, error} = usePage({parameters: {pageId}})

  if (error) {
    let ErrorClass = error.response?.status === 404 ? HTTPNotFound : HTTPError
    throw new ErrorClass(error.response?.statusText)
  }

  return (
    <Box layerStyle={'page'}>
      {/* No components prop needed - registry handles it */}
      <Page page={page} />
    </Box>
  )
}

export default PageViewer
```

#### Step 6: Set Up PageDesignerProvider in App Component

Update your main `_app/index.jsx` to initialize the registry and wrap with PageDesignerProvider:

```jsx
// app/components/_app/index.jsx
import {PageDesignerProvider} from '@salesforce/commerce-sdk-react/components'
import {useUsid} from '@salesforce/commerce-sdk-react'
import {initializeRegistry} from '@salesforce/retail-react-app/app/page-designer/registry'

// Initialize registry synchronously at module load time so components are available during SSR
initializeRegistry()

const App = (props) => {
  const {children} = props
  const {usid} = useUsid()

  // Detect Page Designer mode from URL
  const pageDesignerMode = useMemo(() => {
    const queryParams = location?.search || ''
    if (queryParams.includes('mode=EDIT')) return 'EDIT'
    if (queryParams.includes('mode=PREVIEW')) return 'PREVIEW'
    return undefined
  }, [])

  return (
    <Box className="sf-app">
      {/* Other providers... */}
      <PageDesignerProvider
        clientId="pwa-kit-client"
        targetOrigin="*"
        usid={usid}
        mode={pageDesignerMode}
      >
        {children}
      </PageDesignerProvider>
    </Box>
  )
}
```

**Key setup points**:

1. **Initialize registry at module level** (outside the component) so components are available during SSR.
2. **Pass `usid`** from `useUsid()` hook to the provider for session tracking.
3. **Detect mode from URL** - Page Designer passes `mode=EDIT` or `mode=PREVIEW` as query parameters.
4. **Always wrap with PageDesignerProvider** - it handles both design mode and normal rendering.

#### Step 7: Create PageDesignerInit Component

Create `app/components/page-designer-init/index.jsx` to handle design mode behaviors:

```jsx
import React, {useEffect} from 'react'
import {Prompt} from 'react-router-dom'
import {usePageDesignerMode} from '@salesforce/commerce-sdk-react/components'
import {useGlobalAnchorBlock} from '@salesforce/retail-react-app/app/hooks/use-global-anchor-block'

export function PageDesignerInit() {
  const {isDesignMode} = usePageDesignerMode()

  useGlobalAnchorBlock(isDesignMode)

  useEffect(() => {
    if (isDesignMode) {
      void import('@salesforce/storefront-next-runtime/design/styles.css')
    }
  }, [isDesignMode])

  return <Prompt when={isDesignMode} message={() => false} />
}

export default PageDesignerInit
```

#### Step 8: Create useGlobalAnchorBlock Hook

Create `app/hooks/use-global-anchor-block.js` to prevent link navigation in design mode:

```jsx
import {useEffect} from 'react'

export function useGlobalAnchorBlock(enabled = true) {
  useEffect(() => {
    if (typeof window === 'undefined' || !enabled) return

    function preventAnchorClicks(event) {
      const anchor = event.target.closest('a')
      // Allow links with data-pd-allow-link attribute
      if (anchor && !anchor.hasAttribute('data-pd-allow-link')) {
        event.preventDefault()
      }
    }

    document.addEventListener('click', preventAnchorClicks)
    return () => document.removeEventListener('click', preventAnchorClicks)
  }, [enabled])
}
```

#### Step 9: Add PageDesignerInit to App

In `app/components/_app/index.jsx`, render `PageDesignerInit` inside the provider:

```jsx
import {PageDesignerInit} from '@salesforce/retail-react-app/app/components/page-designer-init'

// Inside your App component's return:
;<PageDesignerProvider
  clientId="pwa-kit-client"
  targetOrigin="*"
  usid={usid}
  mode={pageDesignerMode}
>
  <PageDesignerInit />
  {children}
</PageDesignerProvider>
```

#### Step 10: Deploy and Test

1. Deploy your updated cartridge with headless metadata to your SFCC instance.
2. Restart your PWA Kit development server:
   ```bash
   npm start
   ```
3. Verify in Business Manager:
   - Go to **Merchant Tools > Content > Components**.
   - Your components appear with no ISML requirement.
4. Test page rendering:
   - Go to your pages (homepage, PDP, PLP).
   - Components render using the registry.
5. Test in Page Designer:
   - Open the Page Designer visual editor.
   - Edit a page - your PWA Kit site shows in the preview.
   - Drag components - changes show immediately.

### Store Locator Setting Was Renamed and Moved to a Configuration

In PWA Kit v3.12, to consolidate configuration options in one file, the setting for store locator was moved from the [app/constants.js] to [config/default.js] and the setting's name changed from `STORE_LOCATOR_IS_ENABLED` to `storeLocatorEnabled`.

```
module.exports = {
  app: {
      ...
      storeLocatorEnabled: true
  },
```

### Common Migration Challenges

**Challenge**: Custom JavaScript no longer runs **Solution**: Headless components (`arch_type: "headless"`) do **not** run custom JavaScript from Page Designer metadata.

**Example**:

```javascript
// OLD - Custom script in Page Designer (no longer executed)
// This JavaScript will be IGNORED for headless components

// NEW - Implement in your React component
export const MyComponent = ({title, showDiscount}) => {
  // All logic in React code
  const displayPrice = showDiscount ? applyDiscount(price) : price
  return <div>{displayPrice}</div>
}
```

**Challenge**: Forgetting to set `arch_type: "headless"` **Solution**: Always include `"arch_type": "headless"` in your metadata.

**Challenge**: Metadata attributes don't match React props **Solution**: Ensure every `attribute_definition` `id` matches a prop name in your React component.

**Challenge**: Component typeId mismatch **Solution**: The typeId format is `{group}.{componentId}`.

**Challenge**: Layout component regions not rendering **Solution**: Ensure that your metadata includes `region_definitions` and your React component maps over the `regions` prop with `<Region>` components.

**Challenge**: Page route not working **Solution**: For page metadata, include the `route` field with the URL path (for example, `"route": "/"` for homepage).

**Challenge**: Region not found **Solution**: Verify `regionId` matches the region ID in your page data.

**Challenge**: Visual editing not working **Solution**: Ensure `PageDesignerProvider` wraps your content.

## Complete Migration Example

Here's a consolidated before/after example showing the full transformation:

**Before (Old API):**

```jsx
// page-viewer.jsx
import {Page} from '@salesforce/commerce-sdk-react/components'
import ImageTile from './components/image-tile'
import Banner from './components/banner'
import TwoColumn from './components/two-column'

const components = {
  'commerce_assets.imageTile': ImageTile,
  'commerce_assets.banner': Banner,
  'commerce_layouts.twoColumn': TwoColumn
}

function PageViewer({pageData}) {
  return <Page page={pageData} components={components} />
}

// two-column.jsx
import {Region} from '@salesforce/commerce-sdk-react/components'

function TwoColumn({regions}) {
  return (
    <div>
      <Region region={regions.left} />
      <Region region={regions.right} />
    </div>
  )
}
```

**After (New API):**

```jsx
// registry.js
import {registry} from '@salesforce/commerce-sdk-react'

export function initializeRegistry() {
  registry.registerImporter('commerce_assets.imageTile', () => import('./assets/image-tile'))
  registry.registerImporter('commerce_assets.banner', () => import('./assets/banner'))
  registry.registerImporter('commerce_layouts.twoColumn', () => import('./layouts/two-column'))
}

// _app/index.jsx
import {initializeRegistry} from './page-designer/registry'
initializeRegistry() // At module level, not in useEffect

// page-viewer.jsx
import {Page} from '@salesforce/commerce-sdk-react/components'

function PageViewer({pageData}) {
  return <Page page={pageData} />
}

// two-column.jsx
import {Region} from '@salesforce/commerce-sdk-react/components'

function TwoColumn({component}) {
  return (
    <div>
      <Region component={component} regionId="left" />
      <Region component={component} regionId="right" />
    </div>
  )
}
```

